	/** [sql-warehousing.xml] WarehousingMapper.getOutputChk **/
    SELECT *
    FROM TB_ST_03
    WHERE ST03_COMPANY = #{company}
      AND ST03_FACTORY = #{factory}
      AND ST03_CODE = #{st02Code}
      AND ST03_LOT = #{st02Lot}
      AND ST03_LOT_SEQ = #{st02LotSeq}

mapper.update:
    	/** [sql-warehousing.xml] WarehousingMapper.updateOfPdStock **/
		UPDATE tb_st_01
		 -- 재고수량을 변경하는 경우
	    	SET st01_qty = st01_qty - #{outQty} + #{ipQty}

		 -- 재고 차감 (출고등록/입고삭제)
	    	SET st01_qty =  st01_qty - #{outQty}

	     -- 재고 증가 (입고등록/출고삭제)
	    	SET st01_qty =  st01_qty + #{ipQty}

		 -- 재고실사 품목일때 기존의 수량 0
	    	SET st01_qty = '0'

	    WHERE 1=1
	    AND st01_company = #{company}
	    AND st01_factory = #{factory}
	    AND st01_code = #{code}
	    AND st01_stok = #{stock}

	    	AND st01_lot = #{lot}
			AND st01_lot_seq = #{lotSeq}

	/** [sql-warehousing.xml] WarehousingMapper.updateOfInputHistory **/
    UPDATE tb_st_02
    SET st02_dat = #{st02Dat},
        st02_cus = #{st02Cus},
        st02_gbn = #{st02Gbn},
        st02_qrcode = #{st02Qrcode},
        st02_ipqty = #{st02Ipqty},
        st02_ipunt = #{st02Ipunt},
        st02_status = #{st02Status},
        st02_stok = #{st02Stok},
        st02_dist = #{st02Dist}
    WHERE 1=1
      AND st02_company = #{company}
      AND st02_factory = #{factory}
      AND st02_purno = #{st02Purno}

mapper.select:
		/** [sql-warehousing.xml] WarehousingMapper.getInputHistorySearchInfo **/
        SELECT *
        FROM tb_st_02
        WHERE st02_company = #{company}
          AND st02_factory = #{factory}
          AND st02_pno = #{st02Pno}
        ORDER BY ST02_NO

	/** [sql-warehousing.xml] WarehousingMapper.getSeq **/
    SELECT COALESCE(MAX(st02_seq)+1,1) AS st02_seq
    FROM tb_st_02
    WHERE st02_company = #{company}
      AND st02_factory = #{factory}
      AND TO_CHAR(st02_dat, 'YYYY-MM-DD') = TO_CHAR(SYSDATE, 'YYYY-MM-DD')

	/** [sql-warehousing.xml] WarehousingMapper.getNewLotSeq **/
    SELECT NVL(MAX(ST02_LOT_SEQ)+1, 1) as lot_seq
    FROM TB_ST_02
    WHERE ST02_COMPANY = #{company}
      AND ST02_FACTORY = #{factory}

		/** [sql-warehousing.xml] WarehousingMapper.getAvailable **/
        SELECT *
        FROM tb_qa_05
        WHERE qa05_company = #{company}
          AND qa05_factory = #{factory}
          AND qa05_code = #{cm08Code}
          AND qa05_sdt <= SUBSTR(#{st02Dat},1,10)
          AND qa05_edt >= SUBSTR(#{st02Dat},1,10)

mapper.insert:
	/** [sql-warehousing.xml] WarehousingMapper.insertInspectionConf **/

        select CONCAT(REPLACE(TO_CHAR(sysdate,'YYYY-MM-DD'), '-', '') , lpad(COALESCE(MAX(substr(qa07_no, -5, 5))+1, 1),5,'0'))
        from tb_qa_07
        where qa07_company = #{qa07Company}
        and qa07_factory = #{qa07Factory}
        and TO_CHAR(qa07_dat, 'YYYY-MM-DD') = TO_CHAR(SYSDATE, 'YYYY-MM-DD')

    INSERT INTO tb_qa_07 (
        qa07_company
        , qa07_factory
        , qa07_no
        , qa07_code
        , qa07_gbn
        , qa07_dat
        , qa05_no
        , qa07_lot
        , qa07_lot_seq
        , qa07_status
        , qa07_indte
        , qa07_empno
    ) VALUES (
        #{qa07Company}
        , #{qa07Factory}
        , #{qa07No}
        , #{qa07Code}
        , NVL(#{qa07Gbn},'')
        , #{qa07Dat}
        , #{qa05No}
        , #{qa07Lot}
        , #{qa07LotSeq}
        , #{qa07Status}
        , SYSDATE
        , #{qa07Empno}
    )

